52	SchemaCache::Keys ReadBufferIterator::getKeysForSchemaCache() const
53	{
54	    Strings sources;
55	    sources.reserve(read_keys.size());
56	    std::transform(
57	        read_keys.begin(),
58	        read_keys.end(),
59	        std::back_inserter(sources),
60	        [&](const auto & elem) { return StorageObjectStorageSource::getUniqueStoragePathIdentifier(*configuration, *elem); });
61	    return DB::getKeysForSchemaCache(sources, *format, format_settings, getContext());
62	}
