64	std::optional<ColumnsDescription> ReadBufferIterator::tryGetColumnsFromCache(
65	    const ObjectInfos::iterator & begin,
66	    const ObjectInfos::iterator & end)
67	{
68	    if (!query_settings.schema_inference_use_cache)
69	        return std::nullopt;
70	
71	    for (auto it = begin; it < end; ++it)
72	    {
73	        const auto & object_info = (*it);
74	        auto get_last_mod_time = [&] -> std::optional<time_t>
75	        {
76	            const auto & path = object_info->isArchive() ? object_info->getPathToArchive() : object_info->getPath();
77	            if (!object_info->getObjectMetadata())
78	            {
79	                auto meta = object_storage->tryGetObjectMetadata(path, /*with_tags=*/ false);
80	                if (meta)
81	                    object_info->setObjectMetadata(*meta);
82	            }
83	
84	            return object_info->getObjectMetadata() ? std::optional<time_t>(object_info->getObjectMetadata()->last_modified.epochTime())
85	                                                    : std::nullopt;
86	        };
87	
88	        if (format)
89	        {
90	            const auto cache_key = getKeyForSchemaCache(*object_info, *format);
91	            if (auto columns = schema_cache.tryGetColumns(cache_key, get_last_mod_time))
92	                return columns;
93	        }
94	        else
95	        {
96	            /// If format is unknown, we can iterate through all possible input formats
97	            /// and check if we have an entry with this format and this file in schema cache.
98	            /// If we have such entry for some format, we can use this format to read the file.
99	            for (const auto & format_name : FormatFactory::instance().getAllInputFormats())
100	            {
101	                const auto cache_key = getKeyForSchemaCache(*object_info, format_name);
102	                if (auto columns = schema_cache.tryGetColumns(cache_key, get_last_mod_time))
103	                {
104	                    /// Now format is known. It should be the same for all files.
105	                    format = format_name;
106	                    return columns;
107	                }
108	            }
109	        }
110	    }
111	    return std::nullopt;
112	}
