    if (isNotFoundError(error.GetErrorType()))
        return {};

    throw S3Exception(
        error.GetErrorType(),
        "Failed to get object info: {}. HTTP response code: {}.{}",
        error.GetMessage(),
        static_cast<size_t>(error.GetResponseCode()),
        getAuthenticationErrorHint(error.GetErrorType()));
}

